/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Img,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');
const loadAnton = makeLoadFont('Anton');

const { fontFamily: montserrat } = loadMontserrat();
const { fontFamily: anton } = loadAnton();



export type VintageGunStoryProps = Record<string, any>;

const VintageGunStory: React.FC<VintageGunStoryProps> = ({
  backgroundColor = "#0d0d0d",
  transparentBackground = false,
  durationInSeconds = 10,
  gunImage = "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/15b3ffb435a94d7ba579c1b943e4f19e.png",
  accentColor = "#FF5500",
  textColor = "#FFFFFF",
  scene1Text = "THIS GUY FACETIMES ME...",
  scene2Text = "SENDS A VIDEO OF THE OLDEST GUN",
  scene3Text = "GOTTA MANUALLY PACK THE GUNPOWDER",
  particleCount = 50,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Scene Timings
  const scene1Start = 0;
  const scene2Start = fps * 2.5; // Starts at 2.5 seconds
  const scene3Start = fps * 5.5; // Starts at 5.5 seconds

  // --- Background Grid Animation (3D Scrolling) ---
  const gridPan = interpolate(frame, [0, fps * durationInSeconds], [0, height * 1.5]);

  // --- Camera Shake Effects ---
  const s2Frame = frame - scene2Start;
  const s2ShakeX = s2Frame > 0 && s2Frame < 15 ? Math.sin(s2Frame * 1.5) * (15 - s2Frame) * 0.5 : 0;
  const s2ShakeY = s2Frame > 0 && s2Frame < 15 ? Math.cos(s2Frame * 1.7) * (15 - s2Frame) * 0.5 : 0;

  const s3Frame = frame - scene3Start;
  const s3ShakeX = s3Frame > 0 && s3Frame < 20 ? Math.sin(s3Frame * 2) * (20 - s3Frame) * 0.8 : 0;
  const s3ShakeY = s3Frame > 0 && s3Frame < 20 ? Math.cos(s3Frame * 2.2) * (20 - s3Frame) * 0.8 : 0;

  const shakeX = s2ShakeX + s3ShakeX;
  const shakeY = s2ShakeY + s3ShakeY;

  // --- Scene 1: Facetime/Message ---
  const s1Progress = spring({
    frame: frame - scene1Start,
    fps,
    config: { damping: 14, mass: 1 },
  });
  const s1Exit = spring({
    frame: frame - (scene2Start - 10),
    fps,
    config: { damping: 12 },
  });

  const s1Bob = Math.sin(frame * 0.05) * 8;
  const s1Y = interpolate(s1Progress, [0, 1], [height * 0.1, 0]) - interpolate(s1Exit, [0, 1], [0, height * 0.1]) + s1Bob;
  const s1Opacity = interpolate(s1Progress, [0, 1], [0, 1]) - s1Exit;
  const s1IconPulse = interpolate(Math.sin(frame * 0.1), [-1, 1], [0.95, 1.05]);

  // --- Scene 2: The Gun Reveal ---
  const s2Progress = spring({
    frame: frame - scene2Start,
    fps,
    config: { damping: 10, mass: 1 }, // More bouncy
  });
  
  // Continuous organic float for gun
  const gunFloatY = Math.sin((frame - scene2Start) * 0.05) * 15;
  const gunFloatRotate = Math.sin((frame - scene2Start) * 0.03) * 3;

  const gunPopScale = interpolate(s2Progress, [0, 1], [0.1, 1]);
  const gunSlowZoom = interpolate(frame - scene2Start, [0, fps * 10], [0, 0.4], { extrapolateLeft: "clamp" });
  const gunScale = gunPopScale + gunSlowZoom;
  
  const gunRotate = interpolate(s2Progress, [0, 1], [60, -25]) + gunFloatRotate; 
  const gunY = interpolate(s2Progress, [0, 1], [height * 0.3, 0]) + gunFloatY;
  
  // Dynamic shadow that tracks the gun's float
  const shadowY = interpolate(gunFloatY, [-15, 15], [60, 20]);
  const shadowBlur = interpolate(gunFloatY, [-15, 15], [50, 20]);

  // Fade out Scene 2 text when Scene 3 starts
  const s2TextExit = spring({
    frame: frame - scene3Start,
    fps,
    config: { damping: 12 },
  });

  // --- Scene 3: Gunpowder ---
  const s3Flash = interpolate(frame - scene3Start, [0, 3, 15], [0, 0.5, 0], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp" 
  });

  // Generate deterministic realistic particles for "gunpowder" effect
  const particles = new Array(particleCount).fill(0).map((_, i) => {
    const rX = random(`x-${i}`);
    const rY = random(`y-${i}`);
    const rSpeed = random(`speed-${i}`);
    const rSize = random(`size-${i}`);
    const rWobble = random(`wobble-${i}`);

    const pStartFrame = scene3Start + (rY * fps * 1.5); // Stagger starts
    const pFrame = frame - pStartFrame;
    const clampedFrame = Math.max(0, pFrame);

    const size = interpolate(rSize, [0, 1], [height * 0.003, height * 0.02]);
    const startX = width * 0.2 + (width * 0.6 * rX); // Clustered towards middle
    const startY = height * 0.7 + (height * 0.2 * rY); // Start from lower middle (gun area)

    // Organic rising and wobbling path
    const x = startX + Math.sin(clampedFrame * (0.02 + rWobble * 0.05) + rWobble * 10) * (40 + rWobble * 40);
    const y = startY - (clampedFrame * (rSpeed * 18 + 6)); // Float up faster

    const opacity = interpolate(pFrame, [0, 10, 50, 80], [0, 1, 1, 0], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });

    const isEmber = random(`ember-${i}`) > 0.6;
    const pColor = isEmber ? accentColor : (random(`dark-${i}`) > 0.5 ? "#111111" : "#444444");

    return { id: i, x, y, size, opacity, isEmber, pColor };
  });

  const accentPulse = interpolate(Math.sin(frame * 0.05), [-1, 1], [0.1, 0.25]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      {/* Master Shake Container */}
      <div style={{
        position: 'absolute', width: '100%', height: '100%',
        transform: `scale(1.05) translate(${shakeX}px, ${shakeY}px)`,
      }}>
        
        {/* Dynamic 3D Background Grid */}
        <div style={{
          position: "absolute",
          top: 0, left: 0, width: "100%", height: "100%",
          backgroundColor: transparentBackground ? "transparent" : "#000",
          perspective: "1000px",
          zIndex: 0,
        }}>
          <div
            style={{
              position: "absolute",
              top: "-100%", left: "-100%", width: "300%", height: "300%",
              backgroundImage: `linear-gradient(${backgroundColor} 3px, transparent 3px), linear-gradient(90deg, ${backgroundColor} 3px, transparent 3px)`,
              backgroundSize: "80px 80px",
              backgroundPosition: `0px ${gridPan}px`,
              transform: `rotateX(60deg)`,
              transformOrigin: "center 60%",
              opacity: transparentBackground ? 0 : 0.4,
            }}
          />
        </div>

        {/* Lighting Accent */}
        <div
          style={{
            position: "absolute",
            top: "40%",
            left: "50%",
            transform: "translate(-50%, -50%)",
            width: width * 1.5,
            height: width * 1.5,
            background: `radial-gradient(circle, ${accentColor} 0%, transparent 60%)`,
            opacity: s2Progress > 0 ? accentPulse : 0,
            zIndex: 1,
          }}
        />

        {/* SCENE 1: Facetime Concept */}
        <div
          style={{
            position: "absolute",
            top: height * 0.2,
            left: width * 0.1,
            width: width * 0.8,
            opacity: s1Opacity,
            transform: `translateY(${s1Y}px)`,
            zIndex: 10,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            gap: height * 0.02,
          }}
        >
          <div
            style={{
              width: width * 0.2,
              height: width * 0.2,
              borderRadius: "50%",
              backgroundColor: accentColor,
              border: `4px solid ${textColor}`,
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              transform: `scale(${s1IconPulse})`,
              boxShadow: `0px 15px 30px rgba(0,0,0,0.6)`,
            }}
          >
            <div style={{ width: '40%', height: '30%', backgroundColor: textColor, borderRadius: 4 }} />
            <div style={{ width: 0, height: 0, borderTop: '15px solid transparent', borderBottom: '15px solid transparent', borderLeft: `20px solid ${textColor}`, marginLeft: 2 }} />
          </div>
          <div
            style={{
              backgroundColor: `${textColor}15`,
              padding: "30px 40px",
              borderRadius: 20,
              border: `2px solid ${textColor}30`,
              backdropFilter: "blur(10px)",
              boxShadow: `0px 20px 40px rgba(0,0,0,0.5)`,
            }}
          >
            <h2
              style={{
                fontFamily: montserrat,
                fontWeight: 800,
                fontSize: height * 0.025,
                color: textColor,
                margin: 0,
                textAlign: "center",
                textTransform: "uppercase",
                letterSpacing: 2,
                textShadow: `0px 2px 10px rgba(0,0,0,0.5)`,
              }}
            >
              {scene1Text}
            </h2>
          </div>
        </div>

        {/* SCENE 2 & 3: The Gun */}
        <div
          style={{
            position: "absolute",
            top: 0, left: 0, width: "100%", height: "100%",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            zIndex: 5,
          }}
        >
          <Img
            src={gunImage}
            style={{
              width: "90%",
              objectFit: "contain",
              transform: `translateY(${gunY}px) scale(${gunScale}) rotate(${gunRotate}deg)`,
              filter: `drop-shadow(0px ${shadowY}px ${shadowBlur}px rgba(0,0,0,0.9))`,
              opacity: s2Progress,
            }}
          />
        </div>

        {/* SCENE 2 Text */}
        <div
          style={{
            position: "absolute",
            top: height * 0.15, left: 0, width: "100%",
            padding: `0 ${width * 0.05}px`,
            zIndex: 20,
          }}
        >
          <h1
            style={{
              fontFamily: anton,
              fontSize: height * 0.07,
              textAlign: "center",
              margin: 0,
              lineHeight: 1.1,
              WebkitTextStroke: `2px #000`,
            }}
          >
            {scene2Text.split(" ").map((word, i) => {
              const wordProgress = spring({
                frame: frame - (scene2Start + 10 + i * 4),
                fps,
                config: { damping: 12, mass: 0.8 }
              });
              const opacity = wordProgress - s2TextExit;
              const yOffset = interpolate(wordProgress, [0, 1], [50, 0]) + interpolate(s2TextExit, [0, 1], [0, -30]);
              const isHighlight = word.toUpperCase().includes("OLDEST") || word.toUpperCase().includes("GUN");
              
              return (
                <span
                  key={i}
                  style={{
                    display: "inline-block",
                    marginRight: "15px",
                    color: isHighlight ? accentColor : textColor,
                    transform: `scale(${interpolate(wordProgress, [0, 1], [0.5, 1])}) translateY(${yOffset}px)`,
                    opacity: opacity,
                    textShadow: isHighlight 
                      ? `0px 10px 30px rgba(0,0,0,0.9), 0px 0px 20px ${accentColor}` 
                      : `0px 10px 30px rgba(0,0,0,0.9)`,
                  }}
                >
                  {word}
                </span>
              );
            })}
          </h1>
        </div>

        {/* SCENE 3 Text */}
        <div
          style={{
            position: "absolute",
            bottom: height * 0.15, left: 0, width: "100%",
            padding: `0 ${width * 0.05}px`,
            zIndex: 20,
          }}
        >
          <h1
            style={{
              fontFamily: anton,
              fontSize: height * 0.06,
              textAlign: "center",
              margin: 0,
              lineHeight: 1.1,
              WebkitTextStroke: `2px #000`,
            }}
          >
            {scene3Text.split(" ").map((word, i) => {
              const wordProgress = spring({
                frame: frame - (scene3Start + i * 4),
                fps,
                config: { damping: 12, mass: 0.8 }
              });
              const yOffset = interpolate(wordProgress, [0, 1], [50, 0]);
              const isHighlight = word.toUpperCase().includes("GUNPOWDER");
              
              return (
                <span
                  key={i}
                  style={{
                    display: "inline-block",
                    marginRight: "15px",
                    color: isHighlight ? accentColor : textColor,
                    transform: `scale(${interpolate(wordProgress, [0, 1], [0.5, 1])}) translateY(${yOffset}px)`,
                    opacity: wordProgress,
                    textShadow: isHighlight 
                      ? `0px 10px 30px rgba(0,0,0,0.9), 0px 0px 20px ${accentColor}` 
                      : `0px 10px 30px rgba(0,0,0,0.9)`,
                  }}
                >
                  {word}
                </span>
              );
            })}
          </h1>
        </div>

        {/* SCENE 3: Gunpowder Particles */}
        <div style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%", zIndex: 15, pointerEvents: "none" }}>
          {particles.map((p) => {
            if (p.opacity <= 0) return null;
            const isSpark = random(`spark-${p.id}`) > 0.7;
            const sparkLength = isSpark ? p.size * 3 : p.size;
            
            return (
              <div
                key={p.id}
                style={{
                  position: "absolute",
                  left: p.x,
                  top: p.y,
                  width: sparkLength,
                  height: p.size,
                  backgroundColor: p.pColor,
                  opacity: p.opacity,
                  borderRadius: isSpark ? "4px" : "50%",
                  filter: p.isEmber ? `blur(1px) drop-shadow(0 0 6px ${accentColor})` : "blur(0.5px)",
                  transform: `rotate(${isSpark ? -45 : 0}deg)`,
                }}
              />
            );
          })}
        </div>

        {/* SCENE 3: Flash Effect */}
        <div
          style={{
            position: "absolute",
            top: 0, left: 0, width: "100%", height: "100%",
            backgroundColor: "#FFFFFF",
            opacity: s3Flash,
            zIndex: 45,
            pointerEvents: "none",
            mixBlendMode: "overlay"
          }}
        />

        {/* Cinematic Vignette */}
        <div
          style={{
            position: "absolute",
            top: 0, left: 0, width: "100%", height: "100%",
            background: `radial-gradient(circle at 50% 50%, transparent 40%, rgba(0,0,0,0.7) 120%)`,
            zIndex: 40,
            pointerEvents: "none",
            opacity: transparentBackground ? 0 : 1,
          }}
        />
        
      </div>
    </AbsoluteFill>
  );
};

export default VintageGunStory;